class Recorder extends AudioWorkletProcessor {
  constructor() {
    super();
    this.on = false;
    this.port.onmessage = (e) => { if (e.data.on !== undefined) this.on = e.data.on; };
  }
  process(inputs) {
    const input = inputs[0];
    if (!input || input.length === 0) return true;
    let peak = 0;
    const chans = [];
    for (let c = 0; c < input.length; c++) {
      const src = input[c];
      if (this.on) chans.push(src.slice(0)); // copy: the source is reused
      for (let i = 0; i < src.length; i++) {
        const a = src[i] < 0 ? -src[i] : src[i];
        if (a > peak) peak = a;
      }
    }
    // The meter runs whether or not we're recording, so input can be checked
    // before committing to a take.
    this.port.postMessage(this.on ? { chans, peak } : { peak });
    return true;
  }
}
registerProcessor('stave-recorder', Recorder);
